  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function decodeJwtPayload(token) {
  if (!token || typeof token !== 'string') {
    throw new Error('Missing JWT');
  }

  const [, payload] = token.split('.');
  if (!payload) {
    throw new Error('JWT payload segment is missing');
