    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function decodeJwtPayload(token) {
  if (!token || typeof token !== 'string') {
    throw new Error('Missing JWT');
